#!/usr/bin/env python3
import json
import re
import zipfile
from datetime import datetime
import xml.etree.ElementTree as ET

TEMPLATE_PATH = "/root/clinic_intake_template.hwpx"
DATA_PATH = "/root/patient_intake.json"
OUTPUT_PATH = "/root/clinic_intake_ready.hwpx"

PLACEHOLDER_RE = re.compile(r"\{\{([^}]+)\}\}")


def parse_date_yyyy_mm_dd(s: str) -> datetime.date:
    return datetime.strptime(s, "%Y-%m-%d").date()


def korean_full_year_age(birth_date: str, visit_date: str) -> int:
    b = parse_date_yyyy_mm_dd(birth_date)
    v = parse_date_yyyy_mm_dd(visit_date)
    age = v.year - b.year
    if (v.month, v.day) < (b.month, b.day):
        age -= 1
    return age


def is_phone_placeholder_key(key: str) -> bool:
    k = (key or "").lower()
    return (
        "phone" in k
        or "tel" in k
        or "mobile" in k
        or "callback" in k
        or "contact" in k
        or "전화" in key
        or "연락" in key
        or "회신" in key
    )


def normalize_phone(value: str) -> str:
    digits = re.sub(r"\D", "", value or "")

    # Target format: NNN-NNNN-NNNN (3-4-4)
    if len(digits) == 11:
        return f"{digits[0:3]}-{digits[3:7]}-{digits[7:11]}"

    # Conservative fallbacks (keep digits, or best-effort chunking)
    if len(digits) == 10:
        # Most common 3-3-4
        return f"{digits[0:3]}-{digits[3:6]}-{digits[6:10]}"

    return digits


def localname(tag: str) -> str:
    if tag is None:
        return ""
    if tag.startswith("{") and "}" in tag:
        return tag.split("}", 1)[1]
    return tag


def remove_layout_caches_in_paragraph(p_elem: ET.Element) -> None:
    """Remove stale cached layout elements (LineSeg/lineseg*) anywhere under a modified paragraph."""

    def should_remove(elem: ET.Element) -> bool:
        ln = localname(elem.tag)
        return "lineseg" in ln.lower() or "lineseg" in elem.tag.lower()

    def prune(parent: ET.Element) -> None:
        for child in list(parent):
            if should_remove(child):
                parent.remove(child)
            else:
                prune(child)

    prune(p_elem)


def replace_placeholders(text: str, data: dict, age_note: str | None) -> tuple[str, bool]:
    if not text or "{{" not in text:
        return text, False

    modified = False

    def repl(m: re.Match) -> str:
        nonlocal modified
        key = m.group(1)
        raw_val = data.get(key, "")
        val = "" if raw_val is None else str(raw_val)

        if is_phone_placeholder_key(key):
            val = normalize_phone(val)

        if key == "생년월일" and age_note is not None:
            val = f"{val}{age_note}"

        modified = True
        return val

    return PLACEHOLDER_RE.sub(repl, text), modified


def fill_xml(xml_bytes: bytes, data: dict, age_note: str | None) -> tuple[bytes, bool]:
    """Fill placeholders in an XML file and remove layout caches in modified paragraphs."""
    text = xml_bytes.decode("utf-8")

    # Register known namespaces so output keeps readable prefixes.
    # (ElementTree chooses these registrations when serializing.)
    ET.register_namespace("hp", "http://www.hancom.co.kr/hwpml/2010/HWPML")
    ET.register_namespace("opf", "http://www.idpf.org/2007/opf")

    root = ET.fromstring(text)

    any_modified = False

    # Paragraphs are <hp:p> in this template, but we match by localname to be safe.
    for p in root.iter():
        if localname(p.tag) != "p":
            continue

        para_modified = False

        # Replace within all descendants of the paragraph (text, tail, attrs).
        for elem in p.iter():
            if elem.text and "{{" in elem.text:
                new_text, changed = replace_placeholders(elem.text, data, age_note)
                if changed:
                    elem.text = new_text
                    para_modified = True

            if elem.tail and "{{" in elem.tail:
                new_tail, changed = replace_placeholders(elem.tail, data, age_note)
                if changed:
                    elem.tail = new_tail
                    para_modified = True

            if elem.attrib:
                for k, v in list(elem.attrib.items()):
                    if isinstance(v, str) and "{{" in v:
                        new_v, changed = replace_placeholders(v, data, age_note)
                        if changed:
                            elem.attrib[k] = new_v
                            para_modified = True

        if para_modified:
            remove_layout_caches_in_paragraph(p)
            any_modified = True

    out = ET.tostring(root, encoding="utf-8", xml_declaration=True)
    return out, any_modified


def fill_text(content_bytes: bytes, data: dict, age_note: str | None) -> tuple[bytes, bool]:
    s = content_bytes.decode("utf-8")

    modified = False

    def repl(m: re.Match) -> str:
        nonlocal modified
        key = m.group(1)
        raw_val = data.get(key, "")
        val = "" if raw_val is None else str(raw_val)

        if is_phone_placeholder_key(key):
            val = normalize_phone(val)

        if key == "생년월일" and age_note is not None:
            val = f"{val}{age_note}"

        modified = True
        return val

    out = PLACEHOLDER_RE.sub(repl, s)
    return out.encode("utf-8"), modified


def copy_zipinfo(src: zipfile.ZipInfo) -> zipfile.ZipInfo:
    zi = zipfile.ZipInfo(filename=src.filename, date_time=src.date_time)
    zi.compress_type = src.compress_type
    zi.comment = src.comment
    zi.extra = src.extra
    zi.create_system = src.create_system
    zi.create_version = src.create_version
    zi.extract_version = src.extract_version
    zi.flag_bits = src.flag_bits
    zi.volume = src.volume
    zi.internal_attr = src.internal_attr
    zi.external_attr = src.external_attr
    return zi


def main() -> None:
    with open(DATA_PATH, "r", encoding="utf-8") as f:
        data = json.load(f)

    birth = str(data.get("생년월일", ""))
    visit = str(data.get("방문일", ""))

    age_note = None
    if birth and visit:
        age = korean_full_year_age(birth, visit)
        age_note = f" ({age}세)"

    with zipfile.ZipFile(TEMPLATE_PATH, "r") as zin:
        with zipfile.ZipFile(OUTPUT_PATH, "w") as zout:
            for src_info in zin.infolist():
                src_name = src_info.filename
                raw = zin.read(src_name)

                # Copy directories and binary files as-is
                if src_name.endswith("/"):
                    zout.writestr(copy_zipinfo(src_info), raw)
                    continue

                # Process XML-ish / text-ish files.
                processed = False
                out_bytes = raw

                if src_name.lower().endswith((".xml", ".hpf")):
                    try:
                        out_bytes, _ = fill_xml(raw, data, age_note)
                        processed = True
                    except Exception:
                        # Fallback: best-effort placeholder replacement as plain text
                        try:
                            out_bytes, _ = fill_text(raw, data, age_note)
                            processed = True
                        except Exception:
                            processed = False

                if not processed:
                    # For any other entry: try safe text replacement only if it decodes.
                    try:
                        out_bytes, _ = fill_text(raw, data, age_note)
                    except Exception:
                        out_bytes = raw

                dst_info = copy_zipinfo(src_info)
                zout.writestr(dst_info, out_bytes)


if __name__ == "__main__":
    main()

